/**
 * Shader des rubans.
 *
 * ## L'idee mathematique
 *
 * Chaque ruban est une sinusoide horizontale a sa propre phase, et sa lumiere
 * est une exponentielle de la distance verticale a son axe : loin du ruban la
 * contribution s'eteint, pres de lui elle sature doucement. Les rubans se
 * somment, si bien que leurs croisements s'eclaircissent d'eux-memes.
 *
 * ## Uniforms
 *
 * - `uTime` — temps en secondes, fourni par le moteur.
 * - `uResolution` — taille du canevas en pixels, fournie par le moteur.
 * - `uColorA` — le fond.
 * - `uColorB`, `uColorC` — les deux teintes entre lesquelles les rubans sont
 *   etages, du bas vers le haut.
 * - `uSpeed` — vitesse de l'ondulation.
 * - `uCount` — nombre de rubans, borne a dix.
 * - `uAmplitude` — hauteur de l'ondulation, en fraction du cadre.
 */
export const RIBBONS_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uSpeed;
uniform float uCount;
uniform float uAmplitude;

// Trois sinus de frequences non multiples : ils ne se remettent jamais en
// phase, donc l'ondulation ne se lit pas comme un motif mecanique.
float rubanOnde(float x, float phase) {
  return sin(x * 1.0 + phase) * 0.55
    + sin(x * 2.1 + phase * 1.7) * 0.30
    + sin(x * 3.7 + phase * 0.6) * 0.15;
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float x = vUv.x * aspect * 4.0;
  float t = uTime * uSpeed;

  float rubans = clamp(uCount, 1.0, 10.0);
  vec3 colour = uColorA;

  for (int i = 0; i < 10; i += 1) {
    if (float(i) >= rubans) break;

    float k = (float(i) + 0.5) / rubans;

    // Le dephasage vertical : chaque ruban recoit une phase liee a son rang,
    // sans quoi tous onduleraient d'un seul bloc.
    float axe = k + uAmplitude * rubanOnde(x, t + k * 6.28318);

    // Attenuation par distance a l'axe : une exponentielle, le profil d'une
    // lueur, la ou un simple seuil ferait des bandes plates.
    float ecart = abs(vUv.y - axe);
    float lueur = exp(-ecart * ecart * 2400.0) + exp(-ecart * ecart * 220.0) * 0.35;

    vec3 teinte = mix(uColorB, uColorC, k);
    colour += teinte * lueur * (0.35 + 0.65 * k);
  }

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Rubans : des bandes sinusoidales etagees, qui ondulent en se croisant.
 *
 * ## Le principe
 *
 * Chaque ruban est une sinusoide a sa propre phase ; sa lumiere est une exponentielle de la distance verticale a son axe.
 *
 * Les rubans se somment : leurs croisements s eclaircissent d eux-memes, sans aucun test.
 *
 * ## Ce que ce composant delegue
 *
 * Il ne porte que ce qui le distingue : son shader, ses reglages et son repli.
 * La lecture des tokens, leur conversion en flottants et leur relecture au
 * changement de theme viennent du moteur — les recopier ici en ferait autant
 * de versions a maintenir qu'il y a de fonds.
 *
 * Le repli n'est pas une precaution : il est affiche pendant le chargement du
 * backend, quand WebGL manque, quand l'arbitre refuse la surface — il n'en
 * accorde qu'une par backend — et sous mouvement reduit.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { RIBBONS_FRAGMENT } from './ribbons.shader.js'

/** Ce que l'echappatoire recoit. */
export interface RibbonsControls {
  /** Couleurs effectivement transmises au shader. */
  readonly colours: readonly ShaderColour[]
  /** Motif du refus, s'il y en a un. */
  readonly refused: string | undefined
}

/** Proprietes propres au composant. */
export interface RibbonsOwnProps {
  /** Vitesse de l'ondulation. @defaultValue 0.4 */
  speed?: number
  /** Nombre de rubans. @defaultValue 5 */
  count?: number
  /** Hauteur de l'ondulation, en fraction du cadre. @defaultValue 0.08 */
  amplitude?: number
  /** Tokens dont les couleurs sont lues. */
  colors?: readonly string[]
  /** Classes du repli. */
  fallback?: string
  /** Echappatoire. */
  onReady?: ReadyCallback<RibbonsControls>
}

/** Toutes les proprietes. */
export type RibbonsProps = Customisable<RibbonsOwnProps>

/** Tokens employes par defaut : le fond, puis les deux teintes des rubans. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-teal-400',
  '--o-palette-sky-300',
] as const

/** Repli par defaut : un degrade fige, dans les memes tons. */
const DEFAULT_FALLBACK = 'o-bg-gradient-to-b o-from-zinc-50 dark:o-from-zinc-950 o-to-zinc-50 dark:o-to-sky-950'

/**
 * Rubans.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <Ribbons className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function Ribbons({
  speed = 0.4,
  count = 5,
  amplitude = 0.08,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: RibbonsProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: RIBBONS_FRAGMENT,
    colors,
    uniforms: { uSpeed: speed, uCount: count, uAmplitude: amplitude },
    name: 'ribbons',
    // Chaque ruban ajoute trois sinus et deux exponentielles par fragment :
    // c'est le reglage qui pese, donc celui qui est borne.
    degrade: (quality) => ({
      uCount: quality === 'low' ? Math.min(count, 4) : count,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
